import org.junit.jupiter.api.Test;

/**
 * A SERIALIZABLE observer pins every generation published while it is open, so a long read that interleaves with many
 * writes leaves one generation per write. Releasing the observer must merge that chain with work proportional to its
 * size; merging newest-into-predecessor re-copies the growing tail at every step (quadratic copies, and the deferred
 * model cleanup keeps every intermediate copy alive until compression ends).
 */
class SailSourceBranchLinearCompressionTest {

	private static final SimpleValueFactory VALUES = SimpleValueFactory.getInstance();
	private static final IRI WRITTEN = VALUES.createIRI("urn:compression:written");
	private static final IRI OBSERVED = VALUES.createIRI("urn:compression:observed");
	private static final int WRITES = 400;

	@Test
	void releasingAnObserverMergesPinnedGenerationsWithLinearCopies() {
		AtomicLong additions = new AtomicLong();
		try (SailSourceBranch branch = new SailSourceBranch(new EmptyBacking(), () -> new CountingModel(additions),
				false)) {
			SailDataset observer = branch.dataset(IsolationLevels.SERIALIZABLE);
			try (CloseableIteration<? extends Statement> read = observer.getStatements(null, OBSERVED, null)) {
				assertThat(read.hasNext()).isFalse();
			}
			for (int i = 0; i < WRITES; i++) {
				try (SailSink sink = branch.sink(IsolationLevels.SERIALIZABLE)) {
					sink.approve(VALUES.createIRI("urn:compression:s" + i), WRITTEN, VALUES.createLiteral(i), null);
					sink.flush();
				}
			}

			long beforeRelease = additions.get();
			observer.close();
			long mergeCopies = additions.get() - beforeRelease;

			assertThat(mergeCopies)
					.as("statement copies while merging %s pinned generations", WRITES)
					.isLessThan(4L * WRITES);
			try (SailDataset fresh = branch.dataset(IsolationLevels.SNAPSHOT)) {
				assertThat(fresh.getStatementCount(null, WRITTEN, null)).isEqualTo(WRITES);
			}
		}
	}

	@Test
	void mergedChainKeepsWriteOrderForRemovalsAndReadditions() {
		AtomicLong additions = new AtomicLong();
		IRI subject = VALUES.createIRI("urn:compression:order");
		try (SailSourceBranch branch = new SailSourceBranch(new EmptyBacking(), () -> new CountingModel(additions),
				false)) {
			SailDataset observer = branch.dataset(IsolationLevels.SERIALIZABLE);
			try (CloseableIteration<? extends Statement> read = observer.getStatements(null, OBSERVED, null)) {
				assertThat(read.hasNext()).isFalse();
			}
			// add, remove, re-add one statement and add-then-remove another, each in its own generation
			write(branch, sink -> sink.approve(subject, WRITTEN, VALUES.createLiteral("kept"), null));
			write(branch,
					sink -> sink.deprecate(VALUES.createStatement(subject, WRITTEN, VALUES.createLiteral("kept"))));
			write(branch, sink -> sink.approve(subject, WRITTEN, VALUES.createLiteral("kept"), null));
			write(branch, sink -> sink.approve(subject, WRITTEN, VALUES.createLiteral("dropped"), null));
			write(branch, sink -> sink.deprecate(VALUES.createStatement(subject, WRITTEN,
					VALUES.createLiteral("dropped"))));
			observer.close();

			try (SailDataset fresh = branch.dataset(IsolationLevels.SNAPSHOT);
					CloseableIteration<? extends Statement> statements = fresh.getStatements(subject, WRITTEN,
							null)) {
				assertThat(statements.hasNext()).isTrue();
				assertThat(statements.next().getObject()).isEqualTo(VALUES.createLiteral("kept"));
				assertThat(statements.hasNext()).isFalse();
			}
		}
	}

	private static void write(SailSourceBranch branch, java.util.function.Consumer<SailSink> mutation) {
		try (SailSink sink = branch.sink(IsolationLevels.SERIALIZABLE)) {
			mutation.accept(sink);
			sink.flush();
		}
	}

	private static final class CountingModel extends LinkedHashModel {
		private static final long serialVersionUID = 1L;
		private final transient AtomicLong additions;

		private CountingModel(AtomicLong additions) {
			this.additions = additions;
		}

		@Override
		public boolean add(Statement statement) {
			additions.incrementAndGet();
			return super.add(statement);
		}

		@Override
		public boolean add(Resource subject, IRI predicate, Value object, Resource... contexts) {
			additions.incrementAndGet();
			return super.add(subject, predicate, object, contexts);
		}
	}

	private static final class EmptyBacking extends BackingSailSource {

		@Override
		public SailSink sink(IsolationLevel level) {
			return new SnapshotSailStoreTest.TestSailSink();
		}

		@Override
		public SailDataset dataset(IsolationLevel level) {
			Model empty = new LinkedHashModel();
			return new SailDataset() {
				@Override
				public void close() {
				}

				@Override
				public String getNamespace(String prefix) {
					return null;
				}

				@Override
				public CloseableIteration<? extends Namespace> getNamespaces() {
					return new EmptyIteration<>();
				}

				@Override
				public CloseableIteration<? extends Resource> getContextIDs() {
					return new EmptyIteration<>();
				}

				@Override
				public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
						Value object, Resource... contexts) {
					return new CloseableIteratorIteration<>(empty.filter(subject, predicate, object, contexts)
							.iterator());
				}
			};
		}
	}
}
